) AS (
  VALUES 
    (527::BIGINT, 'Increíble profesor, muy buena persona. Si se esta iniciando en el Tecnológico de Costa Rica el profesor es muy comprensible e inclusive intenta adentrarse más en lo que está por venir. Para las clases de Química Básica I explica muy bien. En LQBI es muy estricto pero lo vale.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-08-12T00:00:00+00:00'::TIMESTAMPTZ, 'a594b879882b51abf9b61f7f5ec7f9fa4a7086dbe3dbf8ba5ca5b24b7fafad1a'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (527::BIGINT, 'El profe es bueno, uno le puede hacer la pregunta más tonta y, el lo enjacha sí, pero también te explicará con calma. Una desventaja y ventaja de él es que solo llega una vez al TEC por lo que se tiene que entregar el informe el mismo día durante el laboratorio, a veces da chance.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '1fe258ce34193a0dc1f67d23f5b0ddf81954c5115963d473f1dd4e6b0aec6ec7'::TEXT, ARRAY[567]::BIGINT[]),
    (527::BIGINT, 'Explica demasiado bien y siempre está dispuesto a ayudar, además es muy buena gente, no dude en matricular con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, '603136a93f75f4636057d666f0e6287c51e3111b430602ac05e2f80d7b811735'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Es muy bueno explicando que hacer en cada Lab, si tiene que preguntarle 100 veces lo que tiene que responder en los informes, 100 veces le va dar la respuesta. Puede tener personalidad dura al principio pero luego le va agarrando cariño al grupo, recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'cb3bb3131218c6eb937fe761001bcf4db26690fd7d49805a30ba737f040360ee'::TEXT, ARRAY[567]::BIGINT[]),
    (527::BIGINT, 'El profesor es muy amable y atento. Siempre aclara la materia las veces que sea necesario y atiende todas las dudas. En algunas ocasiones pierde la paciencia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, '33b6a89dec0e292d983c7955256f61e86a961641952fc8487f3c2bb10a868cf8'::TEXT, ARRAY[613]::BIGINT[]),
    (527::BIGINT, 'Buen profesor. Califica justo. Da quizes extra. Ayuda mucho en horas de consulta. Entrega los resultados de evaluaciones rápido. Una persona agradable y carismática. De las mejores opciones para llevar quimica 2'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2026-01-18T00:00:00+00:00'::TIMESTAMPTZ, '18762140458a371ec988d64842284f74076bcacd30b01f64c8c471b44323f9e3'::TEXT, ARRAY[614]::BIGINT[]),
    (527::BIGINT, 'Un nuen profesor, pero la calificación de los informes es bastante duro y se necesita estudiar para no ir mal con la nota'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'abe93da9bfd9c8da8ee6998612f3638bea69e579d69401fa92eda3df9e339d08'::TEXT, ARRAY[613]::BIGINT[]),
    (527::BIGINT, 'Para química 2 estaba un poco confundido, dicen que para química 1 promete.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-27T00:00:00+00:00'::TIMESTAMPTZ, '1a4b35a8bc0ff9a8962ca5ccb6ab0f74192675f0bd4990c210741665d5717782'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (527::BIGINT, 'Excelente profesor, es claro y hace bastantes ejercicios para comprender el tema, quizá yo no fui muy aplicado, pero aún así, con cumplir lo que solicita y estudiar a tiempo, es pasable, no estudié para el último examen y aún así ya había pasado el curso, el examen también lo pasé chill. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f076bf2ed16dffd5b1bab919fb7079e99c7bd65fbe651c6cff80a36e3692a5c0'::TEXT, ARRAY[614]::BIGINT[]),
    (527::BIGINT, 'Buen profesor, siempre estaba dispuesto a ayudar. Deja prácticas y la materia resumida del libro en el Tec Digital, que ayudaba bastante. Algunas clases la materia no quedaba del todo clara, porque el profe no usaba diapositivas, pero general estuvo bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '2bb0301ad4f250730e3b55b0c1ac6da5fd6fe4cba45e8c2bc9a457a225d8513f'::TEXT, ARRAY[614]::BIGINT[]),
    (527::BIGINT, 'El mae es super buena persona y a la hora de dar instrucciones es muy bueno, eso si, el mae califica durisimo y no regala ni medio punto, si no hace bien el cuaderno de trabajo lo saca de la clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-07-22T00:00:00+00:00'::TIMESTAMPTZ, '0ce24a6728d13f85655ef782c0d007789646bb543e56f4cde1a1964045bc1ae8'::TEXT, ARRAY[613, 567]::BIGINT[]),
    (527::BIGINT, 'Es el mejor profesor que he tenido, atento, se preocupa por que los estudiantes entiendan la materia, explica las veces que haga falta y brinda muchísimo apoyo para poder comprender los temas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '5b00647d046b71065d3c7fb8f353c2774dc8f5a58215ed278df38849fec37667'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Es demasiado bueno, sin duda alguna hizo que química 1 se sintiera demasiado fácil, un excelente profesor que siempre le va a explicar, le va tener paciencia y se preocupa porque entienda los temas, una excelente persona además.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-05-07T00:00:00+00:00'::TIMESTAMPTZ, 'ce74da34b8cfac4f38eaf1868174ddb2d3b36ca1d640dc15eec3556d7a29c8f0'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Es excelente profe, explica genial, se preocupa por sus estudiantes y las clases se hacen muy amenas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '81d45a5714b907c3ad537591e10f707ada4fc0021a8b625c5bd6e95b0cb9123b'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Súper buen profe, recomendadísimo. Explica muy claro y se preocupa porque los estudiantes entiendan. Si va a hora consulta le ayuda mucho. Si puede matricule con él de fijo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-12-07T00:00:00+00:00'::TIMESTAMPTZ, '7d6122035541fc92eb0badc00add689ea6e0b8d86c9d17e71a9f4fb9cb7b44e7'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'El mejor profe para matricular la clase, explica y se entiende bien, obviamente preste atención a lo que dice y haga las prácticas que deja, y si la pulsea, haga prácticas usted mismo, pasa el curso cagándose de risa si le mete pasión con este excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '9b23db02ceb864ca7b9da9b39d4a53c4e7b3914305af38f30d5013d934cb826c'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'El profe es super buena nota y los temas los explica desde 0 entonces uno entiende muy bien'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'da3f4470143a6891250e6917c569e496c629cefa0820083a87077380aa23c058'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Excelente comunicador y docente, el mejor profe del TEC'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-08T00:00:00+00:00'::TIMESTAMPTZ, 'b4b977ced62a346a7175fdb20da7023a1356d28be225927bfc6d1eb1c0486174'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (527::BIGINT, 'Es un curso díficil, pero el profe lo hace llevadero, explica muy bien, se interesa porque usted aprenda, aparte de un gran profesor, es una gran persona.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '4106c08d2a020e837a7cf601ba91ac34e492d7aa1ea2d6dfaeed360eb8cfcbca'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Legalmente si usted se queda a como explica este profe es por que es un vagazo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'd5290949193beb24df175fef7c31d2cab9184a578cd17778da8d68775bddd957'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, '572efb300245e3935c7fd3167561a95d5a722684a7b0828879c025a3767e4ec8'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (527::BIGINT, 'El profe es súper bueno, brinda mucho apoyo al estudiante, se devuelve a repasar algo si es necesario, en general es muy buen profe y se preocupa porque el estudiante aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'b77438b550ac7f3c2b27fba04e725e7e67960528e40e286d59c9d2d24dafeeff'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (527::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-02-09T00:00:00+00:00'::TIMESTAMPTZ, '15e98715bd509720dceb9a7c651130762c7e1e810319f37516adfb5aa0f38d65'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Excelente profesor, explica de una forma muy clara y se devuelve las veces necesarias y algun tema no se entendió. Llevaria otro curso con el, sin pensarlo dos veces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '0091ab183f319f25d72da9ffb91428d3fb70f188e352b5c38111a2262fded810'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Es de los mejores profesores que he tenido en el TEC hasta el momento, súper buena gente y explica muy muy bien y si alguien no entiende se toma su tiempo para explicarlo aun mejor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '291f903cd0d451b3aa8f7d1174ae7e47af0000741a5b53ff53bc4a35a52fe010'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Muy buen profesor, si es necesario explicar un tema que no se entiende 3 veces él con mucho gusto lo explica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '9b26c03fed0f520947b52798659773205759b378e91f879356986b94faf12c9d'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (527::BIGINT, 'El profesor es muy dedicado. Se preocupa por que sus estudiantes entiendan y explica de manera muy clara. Siempre tiene algo debajo de la manga para que uno aprenda más en el curso. 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'fc7c035e0f0ee769aa2f1c4ff7e8c3a583ee52b4cd8e7da2bbd50a2cc1e65a3e'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Fabio es excelente, sabe muchísimo y explica super, en virtualidad se acoplo bastante bien, responde a las dudas que te surjan muy paciente y amable. Lo recomiendo mil!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '362be41e26f3ee003f6edf967997801a006b2197270d93a9aca5d0019e54424c'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Es excelente profesor! Dedicado por lo que hace, excelente respondiendo dudas por correo, virtual el da seguimiento constante a los estudiantes con autoevaluaciones para preparar para los exámenes, prácticas, y mantiene actualizadas las notas y se preocupa porque uno aprenda, recomendadísimo!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'b34e1ba5a45d1513e1887461f1f149eb5e2609a58198ce3eb78c522f9336bcdd'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Sin duda uno de los mejores profes, siempre dispuesto a ayudar, deja bastante tareas pero con orden el curso se pasa super bien con el. Super respetuoso y buena gente'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-18T00:00:00+00:00'::TIMESTAMPTZ, '818971ae67682f2552c6e8bde6f0fa96e55aa18f58a2d669cb47a721bb5c6e70'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Creo 100% que este es de los mejores profes, es paciente, agradable, si tiene que repetir todo, lo repite todo DE BUENA MANERA, respetuoso, uno no se siente como un completo inútil. Lo recomiendo muchísimo. Se adapto muy bien a la virtualidad.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-11-17T00:00:00+00:00'::TIMESTAMPTZ, '2234d15e9cfbb67fffa255f4318965937dc8df064e4eab978c82cd0aeebd04fe'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'En general hace las clases agradables, es muy humano y realmente se preocupa por que usted aprenda. A veces se le cruzan un poco los cables y se le medio enredan las palabras porque quiere ir rápido, sin embargo, su buena calidad compensa cualquier zafis. Lo recomiendo mucho.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-10-06T00:00:00+00:00'::TIMESTAMPTZ, 'c16e4f4d38a8455a591a387013c758390e676cae1f1a401156eb84e490b7897d'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'El es en mi opinión, un ejemplo de profesor, el curso en sí es algo largo (complicado no tanto pero si cansado) el profe explica hasta 2000 veces si es necesario y si tiene una consulta puede realizarla sin ningún temor, es solo de poner atención y tomar una que otra nota sobre algún proceso y listo'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '77a90b79bd844bbfcfd99880d05f24399d990ad3fcc4b19702fd1e4b56e9ae8e'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (527::BIGINT, 'Excelente profesor, tanto virtual como presencial, explica 100 veces si hace falta, se preocupa para que uno de verdad aprenda, si tiene chance de matricular con él, no lo dude'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'acb0f9b8e6a99fb794e9628d7bbc04903193cdee0ecd92b6d94c422747958edd'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (527::BIGINT, 'Excelentes clases virtuales, explica de nuevo cuando no se entiende la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '5c200ac24be259c9161b33c1eb6412cc7ff919457b8ce61c4dbe9ce53f95cfa0'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Demasiado bueno, explica muy bien, si tiene que explicar 10 veces lo hace hasta que entiendan bien, pone ejemplos hasta que entiendan. Se preocupa por que el estudiante de verdad aprenda química, hace resúmenes muy buenos. Si puede matricular con el hágalo sin pensarlo, lo recomiendo mil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '375363d7ffe6fcdf92833a4b86775f23681a8cb93d2c6b7f31911330add6d055'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Excelente profesor, presencial y virtualmente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '1b962fcc0e34f1fa020cafcc249f18b6688beba9787982a14dad176273e3b35b'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Excelente profesor, en las clases deja la materia muy clara y explica 20 veces si alguien lo necesita. Deja los quices para la casa y son bastante fáciles. Hace unas presentaciones y resúmenes súper buenos que ayudan a sacarse una buenta nota. Si tiene la posibilidad de matricular con él no lo dude'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '1ff2fd4d7f3ed7e82d9ae3f2a73fc0c72511ebc3040ac46930af777de1ee2ce5'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'El mejor profe, si tiene la oportunidad de llevar algo con él, no lo piense.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '089d5d275690d1bc07900f3181ff18dfcb4c3db3f2f2288ad86a1a61932c113c'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Pondría más etiquetas, porsue este profe es 10/10, se toma la clase en serio, y busca como explicarle a cada uno si alguien no entiende. Sus clases no son para nada aburridas y ayuda mucho al hacer prácticas en clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, '4291d22008f95914937a8ae96f758eeb2e752ef0068a5aed6aadeb971a15af31'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Él no me da clases a mí y es una lástima pero sin duda matriculo con él próximamente. Me iba muy mal en el curso y no le entendía a mi profesor (CaS) pero un amigo me mandó todo el material que él subía, los vídeos y super claro! No puedo evitar decir que se nota que le interesan los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '8eb0a6e1d4da536f100dae81bc936ddc291748c94f308c5af89facdf488ca1c1'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (527::BIGINT, 'Ni lo dude, matricule con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'cef3690d0818f133693fe47cdafe35afae64c0e8a7f0e26aebf4beceabfd6bc5'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (527::BIGINT, 'El mejor profesor de Quimica del Tecnologico, lo unico malo es creo solo da en el segundo Semestre del año. Los quices son faciles ya que los manda a la casa. No falte con ningun quiz y valla hora de consulta y pasara regalado ese curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-04T00:00:00+00:00'::TIMESTAMPTZ, '6e0d3a696ceabe33138c20ba1a624c3fc623b7333894a82a466e4ab67eb4a924'::TEXT, ARRAY[614]::BIGINT[]),
    (527::BIGINT, 'Excelente profe, creo que es de los mejores que tiene la escuela. Explica claro y da mucha ayuda. Es muy ordenado con los trabajos y pasa actualizando notas rápido. Tiene unos resúmenes maravillosos para los exámenes, simplemente espectacular Fabio.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '8a792a51aa287c00a72843460b100848064862b8751d4928dc7f2871f78b27be'::TEXT, ARRAY[614]::BIGINT[]),
    (527::BIGINT, 'Excelente profesor, explica lo necesario para el examen, atiende las dudas de los estudiantes y deja muchos quices para la casa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '5fa608ae45f83eff8eb4d075691d4fa1d61540e6bb1905c0c815b881f656cb20'::TEXT, ARRAY[614]::BIGINT[]),
    (527::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-25T00:00:00+00:00'::TIMESTAMPTZ, '1ae9312ddcf5843a22ae1905086b9585beb36c0f0b3512dde149ad82eadf0a58'::TEXT, ARRAY[1857]::BIGINT[]),
    (527::BIGINT, 'Matricule con él, no lo dude. En serio es súper bueno y las clases son agradables, se preocupa mucho por sus estudiantes. Hay tareas pero son llevaderas, igual el profe es comprensivo si algo le pasa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-22T00:00:00+00:00'::TIMESTAMPTZ, '6a83b45fed70e15523ce599c34a5257ba4bc55dae849dc95c1803409fff07f69'::TEXT, ARRAY[1857]::BIGINT[]),
    (527::BIGINT, 'Lleve quimica 1 y 2 con el, excelente profesor! Explica super bien y las veces que sea necesario, hasta que el ultimo estudiante comprenda. Es muy amable y comico con ejemplos de la materia. Matriculen a ojos cerrados con el. Si le ponen y les hace falta puntos puede que ayude'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c5b6a8e2ad4e7b171ed657664450d1070a8db8481a01dced5d2f9ad66f813da8'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (527::BIGINT, 'Este profe es EL PROFE! Súper recomendado, se esfuerza para que el estudiante aprenda y hace la de las clases un tiempo súper ameno. Profe si está leyendo esto ¡Gracias!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'b10bed423de66474e1e06b6e32039aceb052d840cff7c91f33d5f40818118525'::TEXT, ARRAY[1857]::BIGINT[]),
    (527::BIGINT, 'El mejor profe de quimica, de verdad si no pasa un curso con el es por vago.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'e811d0a5e6742682ef7165182d4887e21ab26adcf7d9c83d6f640b6b9a3ab530'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'El mejor profesor que he conocido, es super bueno explicando, sus clases son divertidas y se esfuerza mucho en que uno aprenda y es demasiado paciente. Usted no puede ir mejor preparado para un examen si va a clases con él, si se estudia ese resumen, no puede esperar menos de un 90. BEAUTIFUL!!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '8d52ae46081205b0fd44165d0e75b33767d43a3bd81d7f41ca1451158fa86ca6'::TEXT, ARRAY[614]::BIGINT[]),
    (527::BIGINT, 'Excelente profe y persona, atento con los estudiantes, interesado en que se comprenda la materia, incluso brinda resúmenes para los exámenes. Buena opción para llevar el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '2b27a2a6c5540f9253f4fa77c08a16f8d4b4ea5295e070fb8abcc9377c0da877'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Llevé QB I y II con él y es un profe excelente. Él se interesa demasiado porque los estudiantes aprendan y les vaya bien. Hasta hace resúmenes para los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, '53754095358a0605b7e08b39e1c8488472bd7cb22c27b729de58ae98db7692a5'::TEXT, ARRAY[614]::BIGINT[]),
    (527::BIGINT, 'Excelente profesor, es super buena gente, califica como se debe y ayuda mucho si usted no entiende. Se pasa de buen profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '4a788f86f4a9a9a65d63b89b2e2d105e4fb206a64758a8a58c93ce679392acd4'::TEXT, ARRAY[567]::BIGINT[]),
    (527::BIGINT, 'Yo lleve química I y II con el, y para química I es genial super recomendado pero para la II, no lo recomiendo, se enreda mucho con lo que dice y no es muy bueno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'e43393753d80e19fd5d3d05e07a6322b9afa6bdc65179da9b00bcee4a88c98e7'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (527::BIGINT, 'Me atrevería a decir que es hasta mejor que Roldán, super interesado en que los estudiantes aprendan y como el dice, las notas no son lo más importante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-29T00:00:00+00:00'::TIMESTAMPTZ, 'f770a96b82d6d436147fbae01da374b8d714caa9203a1d4d0567a4b1d1d32812'::TEXT, ARRAY[568]::BIGINT[]),
