    (527::BIGINT, 'Maes, no crean esos comentarios negativos que tiene, es un profe increíblemente bueno, la gente que los hizo fue de una clase que tuvo él y lo hicieron para bajarle la nota y así “asegurarse” que iban a poder matricular otra vez con él en QB2 salu2'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'c1d26c67e85a2d78fe2f4254b0f9fd575b698523ede3a1e2edcfd239e51504c5'::TEXT, ARRAY[568]::BIGINT[]),
