    (527::BIGINT, 'Súper buen profe... Muy amable, de verdad le interesa que los estudiantes aprendan. Explica claro y hace varios ejemplos en clase que ayuda a que se facilite la materia. Está super guapoooo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a52d69c6200c79fe70fc8568e757afb8619fcd990d77d2a73d3b8e1c244721ea'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Muy buen profe, se preocupa porque el estudiante entienda, te explica cuantas veces sea necesario. En lo práctico si llega a enrredarse en ocasiones.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e2e228aa206cd14bfd378a106bfee67f00bd49909e2b629eeff8fb4be27219fe'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (527::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '13afb712170ed0861cf56dd27b88b81c3930ddf89179a83d6d8e4d56ce959b8b'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Es un profe excelente, siempre busca cómo hacer que uno entienda de la mejor manera, definitivamente dan hasta ganas de ir a clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '15529fcc1e3cc16fa1e812b539db4312abc79f2dade77661915d51a4bcfe8b2e'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'El mejor profe de química, el que se queda con él es porque quiere, explica demasiado bien, al punto de que se puede ir al examen sin estudiar, es demasiado bueno, no lo piense, si ve cupo agárrelo. Finalmente, está guapo. :P'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ff9f8ed48096b3d9c898dbcce39441ed173b8a841c80011f769e2dce5f8c2b38'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Es el mejor! de verdad que si puede meter con el ni lo piense, explica super claro y siempre se queda al final de la clase con las personas que tengan dudas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'a9d672bbb0a419abdcd4ea612ed611967cb792057e4eae828a7b712c911cc642'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Explica muy bien y se preocupa porque los estudiantes entiendan.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, '1117fafb36b30e4b6ff3815ac9857cd529484778948f9506c5304789b3c5cfcf'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Posiblemente el mejor profe que hay, siempre de preocupa por el estudiante y si algo no entendio, tranquil@ que se lo va a explicar la cantidad de veces que sea necesario! Excelente!!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-05-11T00:00:00+00:00'::TIMESTAMPTZ, '971a0e1d3fcb5d485f38d167e20e2b2bedcb0bf38c4abbe399dd0b74b597ec6d'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-05-10T00:00:00+00:00'::TIMESTAMPTZ, '27a9bc97a9888d315c6d9ae4da938f7fb3904916ed7c1ae7a17c3f7f5676f01e'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (527::BIGINT, 'Es el mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-10T00:00:00+00:00'::TIMESTAMPTZ, '244a8d4f338fa254e855d09a212bf52b6508df69b9528a888fe7417f4c5aab6e'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'El profesor me dió Química 1 y 2 con sus respectivos Laboratorios. Una vez se quedó explicandolos un tema durante 3 horas despues de clase. Es un excelente profesor hace resumenes muy buenos y aclara las dudas. Además no es "tan cuadrado" como los otros profes. Se pasa el curso con 80-90'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-02-01T00:00:00+00:00'::TIMESTAMPTZ, '594020072b3eeda1598c92bc426825755e1c892a9de8908d5d2fbc4734c6a4f1'::TEXT, ARRAY[567, 613]::BIGINT[]),
    (527::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b962908e02d2216a4d7a68810022f963dc9bab8fb6975f228df7d59ab8a4c5c6'::TEXT, ARRAY[568]::BIGINT[]),
    (527::BIGINT, 'Gran profesor, excelente para explicar la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '417832430c22c19261015cf3afd415a6e40c28c2422550024d18ae82569701d2'::TEXT, ARRAY[567]::BIGINT[]),
    (527::BIGINT, 'Excelente profesor. Explica muy claro, califica suave y ayuda un montón al estudiante. Si algo no entendió, el siempre esta dispuesto a ayudarle. Lo recomiendo al 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '6586c7917f77f7f807f872952274131384b8d183412bc5cb37753d0d1f6ca1e0'::TEXT, ARRAY[567]::BIGINT[]),
    (527::BIGINT, 'Él es nuevo en la escuela de Química pero es buenísimo. Súper recomendado, lo ayuda a uno un montón.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'e6218bd309caf95b17b2666f58dcf54fc21e8b179937d013a9f193e2ccfd3976'::TEXT, ARRAY[567]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
